// ---------------------------------------------------------------- settings (O)

export const SETTING_KEYS = ["store_policy", "maintenance", "autopilot", "app_min_versions", "features"] as const;
export type SettingKey = (typeof SETTING_KEYS)[number];

export interface SettingEntry<T> {
  value: T;
  version: number;
  updatedAt: Iso | null;
  updatedBy: StaffRef | null;
}

export type FeatureFlags = { teams: Record<ConfigPlatform, boolean>; gigs: Record<ConfigPlatform, boolean> };

/** `GET /ops/settings` */
export interface OpsSettings {
  store_policy: SettingEntry<Record<ConfigPlatform, StorePolicy>>;
  maintenance: SettingEntry<MaintenanceSetting>;
  autopilot: SettingEntry<AutopilotSettings>;
  app_min_versions: SettingEntry<AppMinVersions>;
  features: SettingEntry<FeatureFlags>;
}

const perPlatform = <T extends z.ZodType>(v: T) => z.strictObject({ ios: v, android: v, web: v });

/** A whole value per key, every field required (the reads fill defaults; a write names everything). */
const maintenanceWrite = perPlatform(z.strictObject({ on: z.boolean({ error: "Choose on or off." }), message: optionalText({ min: 1, max: 280 }) }));
const storePolicyWrite = perPlatform(z.strictObject({ servicesOnly: z.boolean(), verifiedOnly: z.boolean(), showcaseOnly: z.boolean(), teams: z.boolean(), providerAppLink: z.boolean() }));
const flags = perPlatform(z.boolean());
const featuresWrite = z.strictObject({ teams: flags, gigs: flags });
const threshold = z.number({ error: "Enter a number from 0.50 to 1.00." }).min(0.5, "Use 0.50 or more.").max(1, "Use 1.00 or less.").multipleOf(0.01, "Use two decimals.");
const autopilotWrite = z.strictObject({
  enabled: z.boolean(),
  autoApprove: threshold,
  autoReject: threshold,
  scope: z.enum(["all", "qa"], { error: "Choose all accounts or QA accounts only." }),
  checks: z.strictObject({ images: z.boolean(), contact: z.boolean(), listingAi: z.boolean(), paymentMethods: z.boolean(), documents: z.boolean(), chatAi: z.boolean().optional() }),
});

export const SETTING_WRITE_SCHEMAS = {
  store_policy: storePolicyWrite,
  maintenance: maintenanceWrite,
  autopilot: autopilotWrite,
  app_min_versions: appMinVersionsSchema,
  features: featuresWrite,
} as const;

/** `PATCH /ops/settings/{key} { value, version, totp }` (owners, step-up). */
export function settingPatchSchema<K extends SettingKey>(key: K) {
  return z.strictObject({
    value: SETTING_WRITE_SCHEMAS[key],
    version: z.number({ error: "Reload the page and try again." }).int().min(1),
    totp: z.string({ error: "Enter the 6-digit code from your authenticator." }).regex(/^\d{6}$/, "Enter the 6-digit code from your authenticator."),
  });
}

export const isSettingKey = (k: string): k is SettingKey => (SETTING_KEYS as readonly string[]).includes(k);
